{
  "root": "main_stack",
  "state": {
    "workforceData": [
      {
        "year": "2020",
        "employees": 100,
        "turnoverRate": 0.15
      },
      {
        "year": "2021",
        "employees": 110,
        "turnoverRate": 0.12
      },
      {
        "year": "2022",
        "employees": 105,
        "turnoverRate": 0.18
      },
      {
        "year": "2023",
        "employees": 120,
        "turnoverRate": 0.10
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "data_h2",
        "workforce_table",
        "trends_h2",
        "trends_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Annual Workforce Trends",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This analysis provides a comparison of employee count and turnover rates over four years, highlighting key changes in workforce dynamics. The detailed data is presented in the table below."
      },
      "children": []
    },
    "data_h2": {
      "type": "Text",
      "props": {
        "text": "Yearly Employee and Turnover Rate Comparison",
        "variant": "h2"
      },
      "children": []
    },
    "workforce_table": {
      "type": "Table",
      "props": {
        "statePath": "/workforceData",
        "columns": [
          {
            "key": "year",
            "label": "Year"
          },
          {
            "key": "employees",
            "label": "Employees"
          },
          {
            "key": "turnoverRate",
            "label": "Turnover Rate"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "year",
        "highlightColumns": [
          "employees",
          "turnoverRate"
        ],
        "title": "Annual Workforce Data"
      },
      "children": []
    },
    "trends_h2": {
      "type": "Text",
      "props": {
        "text": "Observable Trends",
        "variant": "h2"
      },
      "children": []
    },
    "trends_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "trend_growth",
        "trend_fluctuations",
        "trend_inverse"
      ]
    },
    "trend_growth": {
      "type": "Text",
      "props": {
        "text": "Employee Growth: The total number of employees generally increased over the four-year period, growing from 100 in 2020 to 120 in 2023. There was a slight dip in employee count in 2022 before a significant increase in 2023."
      },
      "children": []
    },
    "trend_fluctuations": {
      "type": "Text",
      "props": {
        "text": "Turnover Rate Fluctuations: The turnover rate showed more variability. It decreased from 0.15 in 2020 to 0.12 in 2021, suggesting improved retention. However, it then peaked at 0.18 in 2022, indicating a period of higher employee departures. The rate then dropped to its lowest point of 0.10 in 2023, coinciding with the largest employee growth."
      },
      "children": []
    },
    "trend_inverse": {
      "type": "Text",
      "props": {
        "text": "Inverse Relationship in 2022-2023: Notably, the year 2022 saw a decrease in employees and the highest turnover rate. Conversely, 2023 experienced the highest employee count and the lowest turnover rate, suggesting successful retention strategies or improved employee satisfaction in that year."
      },
      "children": []
    }
  }
}
